import {useEffect, useState} from 'react';
import {useCEProductCustomization} from './useCEProductCustomization';
import {useCEPreviewerAnimations} from './hooks/useCEPreviewerAnimations';
const defaultImage = `data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI1MCIgaGVpZ2h0PSIxNTAiIHZpZXdCb3g9IjAgMCA1MCAxNTAiPjwvc3ZnPg==`;
export function CEProductCustomizationPreview({
  competitionHandle,
  playerHandle,
  playerSlug,
  productType = 'jersey',
  productHandle,
  productVariant,
  applyAllAddOns: applyAllAddOnsProp = false,
  customizationHookConfig,
  showProductImage = false,
  isAlwaysVisible = true,
  customizationName: customizationNameProp,
  customizationNumber: customizationNumberProp,
  customizationType,
}) {
  const {
    applyAllAddOns,
    setPlayerByHandle,
    setPlayerBySlug,
    setCompetitionByHandle,
    store,
    setStore,
  } = useCEProductCustomization(customizationHookConfig);
  const {
    currentFont,
    currentAddOns,
    customizationName,
    customizationNumber,
    isLoadingCustomization,
    currentProduct,
    currentCustomizationType,
    currentProductVariant,
    currentCompetition,
    currentPlayer,
  } = store;
  const [nameImageUrls, setNameImageUrls] = useState([]);
  const [numberImageUrls, setNumberImageUrls] = useState([]);
  const [showCustomizationPreview, setShowCustomizationPreview] =
    useState(false);
  const [allCharImagesLoadedPromise, setAllCharImagesLoadedPromise] =
    useState(null);
  const {
    lettersAnimationClass,
    numbersAnimationClass,
    productImageAnimClass,
    displayedProductImageUrl,
    displayedName,
    displayedNumber,
    setProductImageAnimClass,
    completeFadeOutTransition,
    completeFadeInTransition,
    showAddOns,
  } = useCEPreviewerAnimations({
    currentProduct,
    nameImageUrls,
    numberImageUrls,
    currentCustomizationType: currentCustomizationType ?? undefined,
    allCharImagesLoadedPromise,
    isLoadingCustomization,
  });
  useEffect(() => {
    setShowCustomizationPreview(
      isAlwaysVisible ||
        !!(
          customizationName?.length > 0 ||
          customizationNumber?.toString().length > 0 ||
          (currentAddOns && currentAddOns.length > 0)
        ),
    );
  }, [isAlwaysVisible, customizationName, customizationNumber, currentAddOns]);
  useEffect(() => {
    if (isLoadingCustomization === false) {
      if (applyAllAddOns && applyAllAddOnsProp) {
        applyAllAddOns();
      }
      if (playerHandle && !currentPlayer) {
        setPlayerByHandle(playerHandle);
      }
      if (playerSlug && !currentPlayer) {
        setPlayerBySlug(playerSlug);
      }
      if (competitionHandle) {
        setCompetitionByHandle(competitionHandle);
      }
      if (customizationType && !currentCustomizationType) {
        setStore({currentCustomizationType: customizationType});
      }
    }
  }, [
    applyAllAddOns,
    applyAllAddOnsProp,
    playerHandle,
    setPlayerByHandle,
    competitionHandle,
    setCompetitionByHandle,
    isLoadingCustomization,
    customizationType,
    setStore,
    currentCompetition,
    currentCustomizationType,
    currentPlayer,
    setPlayerBySlug,
    playerSlug,
  ]);
  useEffect(() => {
    if (productHandle) {
      setStore({currentProductHandle: productHandle});
    }
    if (productVariant && !currentProductVariant) {
      setStore({currentProductVariant: productVariant});
    }
    if (customizationNameProp !== undefined) {
      setStore({customizationName: customizationNameProp});
    }
    if (customizationNumberProp !== undefined) {
      setStore({customizationNumber: customizationNumberProp + ''});
    }
  }, [
    setStore,
    productHandle,
    customizationNameProp,
    customizationNumberProp,
    productVariant,
    currentProductVariant,
  ]);
  useEffect(() => {
    if (currentFont && currentCustomizationType === 'player') {
      const {promise, resolve} = Promise.withResolvers();
      setAllCharImagesLoadedPromise(promise);
      // preload only the images needed for the current name and number in player customization to optimize performance
      // promise all to ensure all images are loaded before displaying the preview to avoid flashes of unstyled content
      Promise.all(
        [...customizationName.toUpperCase(), ...(customizationNumber + '')].map(
          (char) => {
            return new Promise((resolve) => {
              const charCode = char.toUpperCase().charCodeAt(0).toString();
              const matchingImage = currentFont?.images?.find((img) =>
                img.image.url.includes(`/${charCode}_`),
              );
              const imageUrl =
                matchingImage?.image?.url?.split('?')[0] || defaultImage;
              const imgPreload = new Image();
              imgPreload.src = imageUrl;
              imgPreload.onload = () => resolve(imgPreload);
            });
          },
        ),
      ).then(() => {
        resolve();
      });
    }
  }, [
    currentFont,
    currentCustomizationType,
    customizationName,
    customizationNumber,
  ]);
  useEffect(() => {
    if (
      currentCustomizationType &&
      currentCustomizationType !== 'player' &&
      currentFont
    ) {
      const {promise, resolve} = Promise.withResolvers();
      setAllCharImagesLoadedPromise(promise);
      // preload all font images for non-player customization to ensure smooth display of any character, since any character could potentially be used and we don't want to wait for them to load when they are needed
      Promise.all(
        currentFont.images.map((img) => {
          return new Promise((resolve) => {
            const imgPreload = new Image();
            imgPreload.src = img.image.url.split('?')[0];
            imgPreload.onload = () => resolve(imgPreload);
          });
        }),
      ).then(() => {
        resolve();
      });
    }
  }, [currentFont, currentCustomizationType]);
  useEffect(() => {
    if (currentFont) {
      let innerCustomizationName = customizationName;
      if (currentCustomizationType === 'player') {
        innerCustomizationName = currentPlayer?.label ?? customizationName;
      }
      setNameImageUrls(
        [...innerCustomizationName.toUpperCase()]
          .filter(
            (c) =>
              currentFont?.chars?.includes(c) ||
              currentCustomizationType === 'player',
          )
          .map((char) => {
            const charCode = char.toUpperCase().charCodeAt(0).toString();
            const matchingImage = currentFont?.images?.find((img) =>
              img.image.url.includes(`/${charCode}_`),
            );
            const imageUrl =
              matchingImage?.image?.url?.split('?')[0] || defaultImage;
            return {
              url: imageUrl,
              char,
            };
          }),
      );
      setNumberImageUrls(
        [...(customizationNumber + '')].map((char) => {
          const charCode = char.charCodeAt(0).toString();
          const matchingImage = currentFont?.images?.find((img) =>
            img.image.url.includes(`/${charCode}_`),
          );
          const imageUrl =
            matchingImage?.image?.url?.split('?')[0] || defaultImage;
          return {
            url: imageUrl,
            char,
          };
        }),
      );
    } else {
      setNameImageUrls([]);
      setNumberImageUrls([]);
    }
  }, [
    currentFont,
    currentPlayer,
    customizationName,
    customizationNumber,
    currentCustomizationType,
  ]);
  return (
    <>
      {showCustomizationPreview && (
        <div className={`Customization__Product-Container ${productType}`}>
          {showProductImage && displayedProductImageUrl && (
            <div
              className={`Customization__ProductImage ${productImageAnimClass} ${productType}`}
              onAnimationEnd={(e) => {
                if (e.target !== e.currentTarget) return;
                if (e.animationName === 'fadeOut') {
                  completeFadeOutTransition();
                }
                if (e.animationName === 'fadeIn') {
                  completeFadeInTransition();
                }
              }}
            >
              <img
                draggable={false}
                loading="lazy"
                src={displayedProductImageUrl}
                alt={currentProduct?.customizationImage?.image?.altText || ''}
                onLoad={() => {
                  setProductImageAnimClass('fade-in');
                  // add a timeout to ensure the fade-in animation is applied after the image source is updated, to avoid cases where the animation doesn't trigger because the image loads too quickly
                  setTimeout(() => {
                    completeFadeInTransition();
                  }, 500);
                }}
              />

              <div className={`Customization__AddOns ${productType}`}>
                {showAddOns &&
                  currentAddOns?.map((addOn) => {
                    return (
                      addOn?.customizationImage?.image?.url && (
                        <img
                          key={addOn.id}
                          src={addOn.customizationImage?.image?.url}
                          alt={addOn.title}
                        />
                      )
                    );
                  })}
              </div>
            </div>
          )}
          {(() => {
            const total = displayedName.length + displayedNumber.length;
            const segments = [];
            let segmentIndex = 0;
            displayedName.forEach((_, index) => {
              if (displayedName[index].char === '|') {
                segmentIndex++;
              } else {
                segments[segmentIndex] = segments[segmentIndex] || [];
                segments[segmentIndex].push(displayedName[index]);
              }
            });
            let globalCharIndex = 0;
            return (
              <div
                className={`Customization__Letters-Numbers_container ${productType}`}
              >
                <div
                  className={`Customization__Letters ${productType} ${currentCompetition?.handle} ${lettersAnimationClass}`}
                >
                  {segments.map((segment, index) => {
                    return (
                      <div
                        key={`segment` + index}
                        className="Customization__Letters_Row"
                      >
                        {segment.map(({url, char}) => {
                          const index = globalCharIndex++;
                          return (
                            <img
                              key={`${url}-${index}`}
                              src={url}
                              alt={char}
                              style={{
                                '--ce-i': index,
                                '--ce-i-rev': total - 1 - index,
                              }}
                            />
                          );
                        })}
                      </div>
                    );
                  })}
                </div>
                <div
                  className={`Customization__Numbers ${productType} ${currentCompetition?.handle} ${numbersAnimationClass}`}
                >
                  {displayedNumber.map(({url, char}, index) => {
                    const globalIndex = displayedName.length + index;
                    return (
                      <img
                        key={`${url}-${index}`}
                        src={url}
                        alt={char}
                        style={{
                          '--ce-i': globalIndex,
                          '--ce-i-rev': total - 1 - globalIndex,
                        }}
                      />
                    );
                  })}
                </div>
              </div>
            );
          })()}
        </div>
      )}
    </>
  );
}
